     1→"use server";
     2→
     3→import { ActionError, orgAction } from "@/lib/actions/safe-actions";
     4→import { AUTH_PLANS } from "@/lib/auth/stripe/auth-plans";
     5→import { getServerUrl } from "@/lib/server-url";
     6→import { stripe } from "@/lib/stripe";
     7→import { z } from "zod";
     8→
     9→export const upgradeOrgAction = orgAction
    10→  .metadata({
    11→    permissions: {
    12→      subscription: ["manage"],
    13→    },
    14→  })
    15→  .inputSchema(
    16→    z.object({
    17→      plan: z.string(),
    18→      annual: z.boolean().default(false),
    19→      successUrl: z.string(),
    20→      cancelUrl: z.string(),
    21→    }),
    22→  )
    23→  .action(
    24→    async ({
    25→      parsedInput: { plan, annual, successUrl, cancelUrl },
    26→      ctx: { org },
    27→    }) => {
    28→      // Find the plan
    29→      const authPlan = AUTH_PLANS.find((p) => p.name === plan);
    30→      if (!authPlan) {
    31→        throw new ActionError(`Plan "${plan}" not found`);
    32→      }
    33→
    34→      // Get the price ID based on annual or monthly
    35→      const priceId = annual
    36→        ? authPlan.annualDiscountPriceId
    37→        : authPlan.priceId;
    38→      if (!priceId) {
    39→        throw new ActionError(`Price ID not found for plan "${plan}"`);
    40→      }
    41→
    42→      // Get or create Stripe customer
    43→      const customerId = org.stripeCustomerId;
    44→
    45→      if (!customerId) {
    46→        throw new ActionError("No Stripe customer ID found");
    47→      }
    48→
    49→      // Create checkout session
    50→      const session = await stripe.checkout.sessions.create({
    51→        customer: customerId,
    52→        payment_method_types: ["card"],
    53→        line_items: [
    54→          {
    55→            price: priceId,
    56→            quantity: 1,
    57→          },
    58→        ],
    59→        mode: "subscription",
    60→        success_url: `${getServerUrl()}${successUrl}?session_id={CHECKOUT_SESSION_ID}`,
    61→        cancel_url: `${getServerUrl()}${cancelUrl}`,
    62→        metadata: {
    63→          organizationId: org.id,
    64→          plan: plan,
    65→        },
    66→        subscription_data: {
    67→          metadata: {
    68→            organizationId: org.id,
    69→            plan: plan,
    70→          },
    71→          trial_period_days: authPlan.freeTrial?.days,
    72→        },
    73→      });
    74→
    75→      if (!session.url) {
    76→        throw new ActionError("Failed to create checkout session");
    77→      }
    78→
    79→      return {
    80→        url: session.url,
    81→      };
    82→    },
    83→  );
    84→

