     3→import { prisma } from "@/lib/prisma";
     4→import { getUser } from "@/lib/auth/auth-user";
     5→import { logger } from "@/lib/logger";
     6→import type { AccountType } from "@/types/auth";
     7→import { auth } from "@/lib/auth";
     8→import { generateSlug } from "@/lib/format/id";
     9→import { getServerUrl } from "@/lib/server-url";
    10→
    11→export async function updateAccountTypeAction(accountType: AccountType) {
    12→  try {
    13→    const currentUser = await getUser();
    14→
    15→    if (!currentUser) {
    16→      throw new Error("User not authenticated");
    17→    }
    18→
    19→    // Update user accountType
    20→    const updatedUser = await prisma.user.update({
    21→      where: { id: currentUser.id },
    22→      data: { accountType },
    23→    });
    24→
    25→    logger.debug(
    26→      `Updated user ${currentUser.id} accountType to ${accountType}`,
    27→    );
    28→
    29→    // If professional, create organization
    30→    if (accountType === "professional") {
    31→      const emailName = currentUser.email.slice(0, 8);
    32→      try {
    33→        await auth.api.createOrganization({
    34→          body: {
    35→            name: `${emailName}'s agency`,
    36→            slug: generateSlug(`${emailName}-agency`),
    37→            logo: `${getServerUrl()}/images/org-logo.png`,
    38→            userId: currentUser.id,
    39→            keepCurrentActiveOrganization: false,
    40→          },
    41→        });
    42→        logger.debug(
    43→          `Created organization for professional user ${currentUser.id}`,
    44→        );
    45→      } catch (err) {
    46→        logger.error("Failed to create organization for professional user", {
    47→          err,
    48→          userId: currentUser.id,
    49→        });
    50→        // Don't throw here, user creation should still succeed
    51→      }
    52→    }
    53→
    54→    return { success: true, user: updatedUser };
    55→  } catch (error) {
    56→    logger.error("Failed to update account type", { error, accountType });
    57→    return {
    58→      success: false,
    59→      error: error instanceof Error ? error.message : "Unknown error",
    60→    };
    61→  }
    62→}
    63→

