     7→type PropertyDetailResult = {
     8→  property: Property | null;
     9→  error: string | null;
    10→};
    11→
    12→export async function getPropertyDetailAction(
    13→  propertyId: string,
    14→): Promise<PropertyDetailResult> {
    15→  try {
    16→    if (!propertyId || typeof propertyId !== "string") {
    17→      return {
    18→        property: null,
    19→        error: "ID du bien invalide",
    20→      };
    21→    }
    22→
    23→    logger.debug(`🏠 [PropertyDetail] Fetching property: ${propertyId}`);
    24→
    25→    const property = await moteurImmoClient.getListingById(propertyId);
    26→
    27→    logger.debug(
    28→      `🏠 [PropertyDetail] Found property: ${property.title} in ${property.city}`,
    29→    );
    30→
    31→    return {
    32→      property,
    33→      error: null,
    34→    };
    35→  } catch (error) {
    36→    logger.error("❌ [PropertyDetail] Failed to fetch property:", error);
    37→
    38→    // Handle different types of errors
    39→    if (error instanceof Error) {
    40→      if (
    41→        error.message.includes("404") ||
    42→        error.message.includes("not found")
    43→      ) {
    44→        return {
    45→          property: null,
    46→          error: "Ce bien n'existe plus ou n'est plus disponible",
    47→        };
    48→      }
    49→    }
    50→
    51→    return {
    52→      property: null,
    53→      error: "Une erreur est survenue lors de la récupération du bien",
    54→    };
    55→  }
    56→}
