     2→"use server";
     3→
     4→import { getUser } from "@/lib/auth/auth-user";
     5→import integrations from "@/integrations";
     6→import { logger } from "@/lib/logger";
     7→import { z } from "zod";
     8→
     9→const PropertyAlertSchema = z.object({
    10→  propertyId: z.string(),
    11→  propertyTitle: z.string().min(1),
    12→  propertyPrice: z.number().positive(),
    13→  propertyLocation: z.string().min(1),
    14→  propertyUrl: z.string().url(),
    15→  alertType: z.enum(["new_property", "price_drop", "back_on_market"]),
    16→  oldPrice: z.number().positive().optional(),
    17→  newPrice: z.number().positive().optional(),
    18→  searchCriteria: z.string().min(1),
    19→});
    20→
    21→type PropertyAlertInput = z.infer<typeof PropertyAlertSchema>;
    22→
    23→export async function sendPropertyAlertAction(input: PropertyAlertInput) {
    24→  try {
    25→    const user = await getUser();
    26→    if (!user) {
    27→      return { success: false, error: "Utilisateur non connecté" };
    28→    }
    29→
    30→    if (!user.email) {
    31→      return { success: false, error: "Email utilisateur requis" };
    32→    }
    33→
    34→    // Validation des données
    35→    const validatedInput = PropertyAlertSchema.parse(input);
    36→
    37→    logger.info("Sending property alert email", {
    38→      propertyId: validatedInput.propertyId,
    39→      userId: user.id,
    40→      alertType: validatedInput.alertType,
    41→      recipientEmail: user.email,
    42→    });
    43→
    44→    // Préparation des données d'alerte
    45→    const alertData = {
    46→      recipientName: user.name || "Utilisateur",
    47→      propertyTitle: validatedInput.propertyTitle,
    48→      propertyPrice: validatedInput.propertyPrice,
    49→      propertyLocation: validatedInput.propertyLocation,
    50→      propertyUrl: validatedInput.propertyUrl,
    51→      alertType: validatedInput.alertType,
    52→      searchCriteria: validatedInput.searchCriteria,
    53→      oldPrice: validatedInput.oldPrice,
    54→      newPrice: validatedInput.newPrice,
    55→    };
    56→
    57→    // Envoi de l'alerte par email
    58→    const emailResult = await integrations.sendPropertyAlert(
    59→      user.email,
    60→      alertData,
    61→    );
    62→
    63→    if (!emailResult.success) {
    64→      logger.warn("Property alert email failed", {
    65→        propertyId: validatedInput.propertyId,
    66→        userId: user.id,
    67→        error: emailResult.error,
    68→      });
    69→      return {
    70→        success: false,
    71→        error: "Impossible d'envoyer l'alerte par email",
    72→      };
    73→    }
    74→
    75→    logger.info("Property alert email sent successfully", {
    76→      propertyId: validatedInput.propertyId,
    77→      userId: user.id,
    78→      messageId: emailResult.data?.messageId,
    79→      recipients: emailResult.data?.recipients.length,
    80→    });
    81→
    82→    return {
    83→      success: true,
    84→      data: {
    85→        messageId: emailResult.data?.messageId,
    86→        status: emailResult.data?.status,
    87→      },
    88→    };
    89→  } catch (error) {
    90→    logger.error("Property alert sending failed", { error });
    91→
    92→    if (error instanceof z.ZodError) {
    93→      return {
    94→        success: false,
    95→        error: `Données invalides: ${error.issues.map((i) => i.message).join(", ")}`,
    96→      };
    97→    }
    98→
    99→    return {
   100→      success: false,
   101→      error: "Erreur lors de l'envoi de l'alerte",
   102→    };
   103→  }
   104→}
   105→
   106→const BulkPropertyAlertSchema = z.object({
   107→  recipientEmails: z.array(z.string().email()).min(1).max(100), // Limite pour éviter les abus
   108→  propertyId: z.string(),
   109→  propertyTitle: z.string().min(1),
   110→  propertyPrice: z.number().positive(),
   111→  propertyLocation: z.string().min(1),
   112→  propertyUrl: z.string().url(),
   113→  alertType: z.enum(["new_property", "price_drop", "back_on_market"]),
   114→  oldPrice: z.number().positive().optional(),
   115→  newPrice: z.number().positive().optional(),
   116→  searchCriteria: z.string().min(1),
   117→});
   118→
   119→type BulkPropertyAlertInput = z.infer<typeof BulkPropertyAlertSchema>;
   120→
   121→export async function sendBulkPropertyAlertAction(
   122→  input: BulkPropertyAlertInput,
   123→) {
   124→  try {
   125→    const user = await getUser();
   126→    if (!user) {
   127→      return { success: false, error: "Utilisateur non connecté" };
   128→    }
   129→
   130→    // Vérification des permissions (exemple: admin ou professionnel)
   131→    if ((user as any).accountType !== "professional") {
   132→      return {
   133→        success: false,
   134→        error: "Action réservée aux comptes professionnels",
   135→      };
   136→    }
   137→
   138→    // Validation des données
   139→    const validatedInput = BulkPropertyAlertSchema.parse(input);
   140→
   141→    logger.info("Sending bulk property alert emails", {
   142→      propertyId: validatedInput.propertyId,
   143→      userId: user.id,
   144→      alertType: validatedInput.alertType,
   145→      recipientCount: validatedInput.recipientEmails.length,
   146→    });
   147→
   148→    // Préparation des données d'alerte
   149→    const alertData = {
   150→      recipientName: "Cher client", // Générique pour les envois en masse
   151→      propertyTitle: validatedInput.propertyTitle,
   152→      propertyPrice: validatedInput.propertyPrice,
   153→      propertyLocation: validatedInput.propertyLocation,
   154→      propertyUrl: validatedInput.propertyUrl,
   155→      alertType: validatedInput.alertType,
   156→      searchCriteria: validatedInput.searchCriteria,
   157→      oldPrice: validatedInput.oldPrice,
   158→      newPrice: validatedInput.newPrice,
   159→    };
   160→
   161→    // Envoi des emails en parallèle (avec limite de concurrence)
   162→    const BATCH_SIZE = 10; // Traiter 10 emails à la fois
   163→    const results = [];
   164→
   165→    for (
   166→      let i = 0;
   167→      i < validatedInput.recipientEmails.length;
   168→      i += BATCH_SIZE
   169→    ) {
   170→      const batch = validatedInput.recipientEmails.slice(i, i + BATCH_SIZE);
   171→      const batchPromises = batch.map(async (email) => {
   172→        try {
   173→          const personalizedData = {
   174→            ...alertData,
   175→            recipientName: "Cher client", // Pourrait être personnalisé avec une base de données
   176→          };
   177→
   178→          const result = await integrations.sendPropertyAlert(
   179→            email,
   180→            personalizedData,
   181→          );
   182→          return {
   183→            email,
   184→            success: result.success,
   185→            messageId: result.data?.messageId,
   186→            error: result.error,
   187→          };
   188→        } catch (error) {
   189→          return {
   190→            email,
   191→            success: false,
   192→            error: error instanceof Error ? error.message : "Unknown error",
   193→          };
   194→        }
   195→      });
   196→
   197→      // eslint-disable-next-line no-await-in-loop
   198→      const batchResults = await Promise.all(batchPromises);
   199→      results.push(...batchResults);
   200→
   201→      // Petite pause entre les batches pour éviter de surcharger le service d'email
   202→      if (i + BATCH_SIZE < validatedInput.recipientEmails.length) {
   203→        // eslint-disable-next-line no-await-in-loop
   204→        await new Promise((resolve) => setTimeout(resolve, 1000));
   205→      }
   206→    }
   207→
   208→    const successCount = results.filter((r) => r.success).length;
   209→    const failureCount = results.length - successCount;
   210→
   211→    logger.info("Bulk property alert emails completed", {
   212→      propertyId: validatedInput.propertyId,
   213→      userId: user.id,
   214→      totalRecipients: results.length,
   215→      successCount,
   216→      failureCount,
   217→    });
   218→
   219→    return {
   220→      success: true,
   221→      data: {
   222→        totalSent: results.length,
   223→        successCount,
   224→        failureCount,
   225→        results: results.map((r) => ({
   226→          email: r.email,
   227→          success: r.success,
   228→          messageId: r.messageId,
   229→          error: r.error,
   230→        })),
   231→      },
   232→    };
   233→  } catch (error) {
   234→    logger.error("Bulk property alert sending failed", { error });
   235→
   236→    if (error instanceof z.ZodError) {
   237→      return {
   238→        success: false,
   239→        error: `Données invalides: ${error.issues.map((i) => i.message).join(", ")}`,
   240→      };
   241→    }
   242→
   243→    return {
   244→      success: false,
   245→      error: "Erreur lors de l'envoi des alertes",
   246→    };
   247→  }
   248→}
