   250→const GeolocationAnalysisSchema = z.object({
   251→  propertyAddress: z.string().min(1),
   252→  radius: z.number().min(100).max(5000).optional().default(1000), // 100m à 5km
   253→  placeTypes: z.array(z.string()).optional(),
   254→});
   255→
   256→type GeolocationAnalysisInput = z.infer<typeof GeolocationAnalysisSchema>;
   257→
   258→export async function analyzePropertyLocationAction(
   259→  input: GeolocationAnalysisInput,
   260→) {
   261→  try {
   262→    const user = await getUser();
   263→    if (!user) {
   264→      return { success: false, error: "Utilisateur non connecté" };
   265→    }
   266→
   267→    // Validation des données
   268→    const { propertyAddress, radius, placeTypes } =
   269→      GeolocationAnalysisSchema.parse(input);
   270→
   271→    logger.info("Starting property location analysis", {
   272→      userId: user.id,
   273→      address: propertyAddress,
   274→      radius,
   275→      placeTypes,
   276→    });
   277→
   278→    // Géocodage de l'adresse
   279→    const geocodingResult = await integrations.geocodeAddress(propertyAddress);
   280→
   281→    if (!geocodingResult.success || !geocodingResult.data) {
   282→      return {
   283→        success: false,
   284→        error: "Impossible de localiser l'adresse fournie",
   285→      };
   286→    }
   287→
   288→    const location = {
   289→      lat: geocodingResult.data.latitude,
   290→      lng: geocodingResult.data.longitude,
   291→    };
   292→
   293→    // Recherche de lieux à proximité
   294→    const typesToSearch = placeTypes ?? [
   295→      "school",
   296→      "hospital",
   297→      "grocery_or_supermarket",
