   304→    const placesPromises = typesToSearch.map(async (placeType) => {
   305→      try {
   306→        const placesResult = await integrations.findNearbyPlaces(
   307→          location,
   308→          radius,
   309→          placeType,
   310→        );
   311→        if (placesResult.success && placesResult.data) {
   312→          return {
   313→            type: placeType,
   314→            places: placesResult.data.places.slice(0, 5), // Limiter à 5 par type
   315→          };
   316→        }
   317→      } catch (error) {
   318→        logger.debug(`Failed to find places of type ${placeType}`, { error });
   319→      }
   320→      return null;
   321→    });
   322→
   323→    const placesResults = await Promise.all(placesPromises);
   324→    const nearbyPlaces = placesResults.filter((result) => result !== null);
   325→
   326→    // Calcul de distances vers des points d'intérêt importants
   327→    const importantDestinations = [
   328→      {
   329→        name: "Gare la plus proche",
   330→        address: `gare ${propertyAddress.split(",")[0]}`,
