   352→      } catch (error) {
   353→        logger.debug(`Failed to calculate distance to ${destination.name}`, {
   354→          error,
   355→        });
   356→      }
   357→      return null;
   358→    });
   359→
   360→    const distanceResults = await Promise.all(distancePromises);
   361→    const distances = distanceResults.filter((result) => result !== null);
