     8→import type { NegotiationReportRequest, NegotiationReport } from "./types";
     9→
    10→/**
    11→ * Génère un rapport de négociation pour une propriété
    12→ */
    13→export async function generateNegotiationReportAction(
    14→  request: NegotiationReportRequest,
    15→): Promise<NegotiationReport> {
    16→  const session = await auth.api.getSession({
    17→    headers: await headers(),
    18→  });
    19→
    20→  if (!session?.user.id) {
    21→    redirect("/auth/signin");
    22→  }
    23→
    24→  // Vérifier que l'utilisateur a accès à cette propriété (via ses favoris)
    25→  const favorite = await prisma.favorite.findFirst({
    26→    where: {
    27→      userId: session.user.id,
    28→      property: {
    29→        externalId: request.propertyId,
    30→      },
    31→    },
    32→    include: {
    33→      property: true,
    34→    },
    35→  });
    36→
    37→  if (!favorite) {
    38→    throw new Error(
    39→      "Vous devez avoir ce bien en favoris pour générer un rapport de négociation",
    40→    );
    41→  }
    42→
    43→  const property = favorite.property;
    44→
    45→  // Vérifications des données nécessaires
    46→  if (!property.surface) {
    47→    throw new Error(
    48→      "La surface du bien est nécessaire pour l'analyse de négociation",
    49→    );
    50→  }
    51→
    52→  if (!property.postalCode) {
    53→    throw new Error("Le code postal du bien est nécessaire pour l'analyse DVF");
    54→  }
    55→
    56→  // Générer le rapport
    57→  const report = await negotiationAnalysisService.generateNegotiationReport(
    58→    property,
    59→    request.userComments,
    60→  );
    61→
    62→  // Optionnel : Sauvegarder le rapport en base pour historique
    63→  // await prisma.negotiationReport.create({ ... });
    64→
    65→  return report;
    66→}
    67→
    68→/**
    69→ * Récupère l'historique des rapports de négociation de l'utilisateur
    70→ */
    71→export async function getUserNegotiationReportsAction() {
    72→  const session = await auth.api.getSession({
    73→    headers: await headers(),
    74→  });
    75→
    76→  if (!session?.user.id) {
    77→    redirect("/auth/signin");
    78→  }
    79→
    80→  // Pour l'instant, retourne un tableau vide
    81→  // En production, on récupèrerait l'historique depuis la base
    82→  return [];
    83→}
    84→
    85→/**
    86→ * Action pour tester l'analyse DVF d'une propriété
    87→ */
    88→export async function testDVFAnalysisAction(propertyExternalId: string) {
    89→  const session = await auth.api.getSession({
    90→    headers: await headers(),
    91→  });
    92→
    93→  if (!session?.user.id) {
    94→    redirect("/auth/signin");
    95→  }
    96→
    97→  const property = await prisma.property.findUnique({
    98→    where: { externalId: propertyExternalId },
    99→  });
   100→
   101→  if (!property) {
   102→    throw new Error("Propriété non trouvée");
   103→  }
   104→
   105→  if (!property.surface || !property.postalCode) {
   106→    throw new Error("Données insuffisantes pour l'analyse DVF");
   107→  }
   108→
   109→  // Test simple de l'analyse DVF
   110→  const dvfService = await import("@/integrations/b2c/services/dvf.service");
   111→  const service = new dvfService.DVFService();
   112→
   113→  const comparison = await service.compareWithMarket(
   114→    property.price,
   115→    property.surface,
   116→    property.category === "apartment" ? "Appartement" : "Maison",
   117→    property.city,
   118→    property.postalCode,
   119→  );
   120→
   121→  return comparison;
   122→}
