   234→          )}
   235→          
   236→          {!dpeExpanded && dpeData.dpeClass && (
   237→            <div className="flex items-center gap-3 p-3 bg-muted rounded-lg">
   238→              <div className="flex items-center gap-2">
   239→                <span className="text-xs text-muted-foreground">DPE</span>
   240→                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${
   241→                  dpeData.dpeClass === "A" || dpeData.dpeClass === "B" ? "bg-green-500 text-white" :
   242→                  dpeData.dpeClass === "C" || dpeData.dpeClass === "D" ? "bg-yellow-400 text-black" :
   243→                  "bg-red-500 text-white"
   244→                }`}>
   245→                  {dpeData.dpeClass}
   246→                </div>
   247→              </div>
   248→              
   249→              {dpeData.rentalRestrictionRisk && (
   250→                <div className="flex items-center gap-2">
   251→                  <span className="text-xs text-muted-foreground">Risque location</span>
   252→                  <Badge variant={
   253→                    dpeData.rentalRestrictionRisk === "critical" ? "destructive" :
   254→                    dpeData.rentalRestrictionRisk === "high" ? "destructive" :
   255→                    dpeData.rentalRestrictionRisk === "medium" ? "default" : "secondary"
   256→                  } className="text-xs">
   257→                    {dpeData.rentalRestrictionRisk === "critical" ? "Critique" :
   258→                     dpeData.rentalRestrictionRisk === "high" ? "Élevé" :
   259→                     dpeData.rentalRestrictionRisk === "medium" ? "Moyen" : "Faible"}
   260→                  </Badge>
   261→                </div>
   262→              )}
   263→              
   264→              {dpeData.annualEnergyCost && (
   265→                <div className="flex items-center gap-2">
   266→                  <span className="text-xs text-muted-foreground">Coût/mois</span>
   267→                  <span className="text-sm font-semibold">
   268→                    {Math.round(dpeData.annualEnergyCost / 12)}€
   269→                  </span>
   270→                </div>
   271→              )}
   272→            </div>
   273→          )}
   274→        </div>
   275→
   276→        {/* Notes section */}
   277→        <div className="space-y-2">
   278→          <h4 className="text-sm font-medium">Notes personnelles :</h4>
   279→          {isEditing ? (
   280→            <div className="space-y-2">
   281→              <Textarea
   282→                value={notes}
   283→                onChange={(e) => setNotes(e.target.value)}
   284→                placeholder="Ajoutez vos notes sur ce bien..."
   285→                className="min-h-[80px]"
   286→                maxLength={500}
   287→              />
   288→              <div className="flex items-center justify-between">
   289→                <p className="text-muted-foreground text-xs">
   290→                  {notes.length}/500 caractères
   291→                </p>
   292→                <div className="flex items-center gap-2">
   293→                  <Button
   294→                    onClick={handleCancel}
   295→                    variant="outline"
   296→                    size="sm"
   297→                    disabled={isLoading}
   298→                  >
   299→                    <X className="mr-1 h-3 w-3" />
   300→                    Annuler
   301→                  </Button>
   302→                  <Button onClick={handleSave} size="sm" disabled={isLoading}>
   303→                    <Save className="mr-1 h-3 w-3" />
   304→                    Sauvegarder
   305→                  </Button>
   306→                </div>
   307→              </div>
   308→            </div>
   309→          ) : (
   310→            <div className="space-y-2">
   311→              {favorite.notes ? (
   312→                <p className="bg-muted rounded-md p-3 text-sm whitespace-pre-wrap">
   313→                  {favorite.notes}
   314→                </p>
   315→              ) : (
   316→                <p className="text-muted-foreground text-sm italic">
   317→                  Aucune note pour ce bien
   318→                </p>
   319→              )}
   320→            </div>
   321→          )}
   322→        </div>
   323→
   324→        {/* Actions */}
   325→        <div className="flex items-center justify-between gap-2">
   326→          <div className="text-muted-foreground text-xs">
   327→            Ajouté le {new Date(favorite.createdAt).toLocaleDateString("fr-FR")}
   328→          </div>
   329→
   330→          <div className="flex items-center gap-1">
   331→            {favorite.property.sourceUrl && (
   332→              <Button asChild variant="ghost" size="sm" title="Voir l'annonce">
   333→                <a
   334→                  href={favorite.property.sourceUrl}
   335→                  target="_blank"
   336→                  rel="noopener noreferrer"
   337→                >
   338→                  <ExternalLink className="h-4 w-4" />
   339→                </a>
   340→              </Button>
   341→            )}
   342→
   343→            <Button
   344→              onClick={() => setIsEditing(!isEditing)}
   345→              variant="ghost"
   346→              size="sm"
   347→              disabled={isLoading}
   348→              title="Modifier les notes"
   349→            >
   350→              <Edit3 className="h-4 w-4" />
   351→            </Button>
   352→
   353→            <Button
   354→              onClick={handleDelete}
   355→              variant="ghost"
   356→              size="sm"
   357→              disabled={isLoading}
   358→              title="Supprimer des favoris"
   359→              className="text-destructive hover:text-destructive"
   360→            >
   361→              <Trash2 className="h-4 w-4" />
   362→            </Button>
   363→          </div>
   364→        </div>
   365→      </CardContent>
   366→    </Card>
   367→  );
   368→}
